def canonical_chunks(value, budget):
    parts, length = [], 0
    for piece in json.JSONEncoder(sort_keys=True, separators=(',', ':'), ensure_ascii=False,
                                  allow_nan=False).iterencode(value):
        parts.append(piece)
        length += len(piece)
        if length >= 16384:
            budget.check()
            yield ''.join(parts).encode('utf8')
            parts, length = [], 0
    if parts:
        budget.check()
        yield ''.join(parts).encode('utf8')
